<style>
    .loadMoreItem {
        display: inline-block;
    }   
</style>


<div class="row well well-sm no-border bg-color-white ">
    <div class="alert alert-info" role="alert" style="display: block">Sem aulas para exibir</div>

</div>
<!-- /container -->

<div class="container">
    <div class="row">
        <div class="col-sm-12">
            <div class="page-footer">
            </div>
        </div>
    </div>
</div>

<script>
    function redirect_blank(url) {
        //window.open(url, '_blank');
        var a = document.createElement('a');
        a.target = "_blank";
        a.href = url;
        a.click();
    }


    function oldestExamPublish(oldest, examPublishMainId, examTitle) {
        var oldestExamPublishId;
        var oldestExamTitle;
        var oldestExamEndDate;
        //Como o modelo traz uma lista eu precisei verificar se havia alguma prova que não havia tentativas e fosse a mais velha.

        //É a prova mais velha ou não há provas com 0 tentativas, abre a avaliação direto.
        if (JSON.parse(oldest) || 0 == 0) {
            redirect_blank('/ExamPublish/ExamStudent?id=' + examPublishMainId)
        }
        else {
            //Modal notificando que há uma avaliação que não foi feita nenhuma tentativa e vai encerrar antes que a que foi clicada.
            $.ajax({
                url: "/Home/OldEvaluationAlertModal",
                type: "POST",
                data: {
                    desiredExamPublishId: examPublishMainId,
                    desiredExamTitle: examTitle,
                    oldestExamPublishId: oldestExamPublishId,
                    oldestExamTitle: oldestExamTitle,
                    oldestExamEndDate: oldestExamEndDate,
            }
            }).done(function (data) {
                $("#oldEvaluationAlert").html(data);
                $("#oldEvaluationAlertModal").show();
            });
        }
    }
    function setOverlayOn(classroomDisciplineId) {
        $("#card_" + classroomDisciplineId).css('filter', 'blur() brightness(0.7)');
    }
    function setOverlayOff(classroomDisciplineId) {
        $("#card_" + classroomDisciplineId).css('filter', 'none');
    }

    $(document).ready(function () { 
        $(".openMaterial").on("click", function () {
            var classId = $(this).data("classid");
            page.OpenMaterial(classId);
        });

        //inicia botão de carregar mais
        $(".loadMore").loadMoreResults({
            displayedItems: 12,
            showItems: 4,
            button: {
                class: "btn btn-success",
                text: "Carregar mais"
            }
        });
    });
</script>"}

